// app_cardler.cpp — "Cardler": a top-down mini-RPG on the SAME tile sandbox as Orde (app_vs): an SD raw
// 8bpp RGB332 atlas with an exact magenta key (tile_blit.h, which matches the device canvas and blits
// straight into it), a camera over a tile world, held-key + tilt movement.
//
// The WORLD is generated by assets/cardler/worldgen.mjs into cardler_world.h — TWO run-length tile layers:
// BASE (opaque terrain) + OVR (transparent props drawn keyed on top), per-ASCII lookup tables, and an ENT[]
// table (NPCs, beasts, rats). Props keep whatever terrain is under them. A row is decoded on the stack
// when it is drawn (rle_row) and single tiles are looked up for collision (rle_at).
//
// The game: find every chest in the kingdom. Beasts and spirits bite on contact (and knock you back),
// talking to a villager restores your HP, fainting wakes you at the village with half your gold. Progress
// (position, HP, gold, opened chests) is saved to SD on leaving play; a save that does not read back
// intact is never overwritten except by an explicit "New game".
//
// Look: the shared console kit (game_ui.h) for title, menus and cards; in play, outlined sprites over
// dithered (translucent) shadows and torch light, floating gold / damage numbers, a hit shake.
// Controls mirror Orde: W/E up, A/S down, I left, O right (or the arrows), diagonals with two keys; on the
// ADV a tilt controller is COMPLEMENTARY to the keyboard. Text follows the OS language (game_text.h).
// RAM: NX_SOLO; the atlas (4 KB chunks) is heap-on-enter, the run state is APP_RAM — nothing big in .bss.
#include "nucleo_app.h"
#include "nucleo_kbd.h"
#include "launcher_theme.h"      // W H HINT
#include "app_gfx.h"             // 'd' = canvas
#include "nucleo_exclusive.h"    // NX_SOLO
#include "esp_timer.h"
#include "cardler_world.h"       // enum C_*, MAP_W/H, BASE/OVR (+_ROW), TIDb/SOLb/TIDo/SOLo/FLPo[128], ENT[]/NENT
#include "tile_blit.h"           // shared 8bpp atlas + blitters, also used by Orde
#include "nucleo_imu.h"          // ADV tilt sensor (complementary control)
#include "game_text.h"           // the five OS languages (it/en in flash, es/fr/de from the SD pack)
#include "game_ui.h"             // gui:: the console kit (title, menu, dialog, text)
#include "game_sfx.h"            // shared SFX: the PC-rendered pack, else a tone
#include <M5GFX.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <math.h>
#include <stddef.h>
#include <sys/stat.h>

#define DIRP       "/sd/data/Cardler"
#define ATLAS_PATH DIRP "/atlas.bin"       // raw 8bpp RGB332, C_N x (16x16), magenta key
#define CFG_PATH   DIRP "/settings.json"
#define SAVE_PATH  DIRP "/save.bin"
#define STEP_US    33333                  // 30 Hz game step
#define HPMAX      10
#define MAXCHEST   32
#define NPOP       6                      // floating numbers on screen at once
#define COL_ACC    0x3FE6                 // Cardler green
#define COL_GOLD   0xFEA0
#define COL_MUT    0x9CD3

enum { GS_MENU, GS_SETTINGS, GS_PLAY, GS_PAUSE, GS_OVER, GS_WIN };
static int s_gs = GS_MENU;
static gui::Menu s_menu, s_setm;

// ---- sound: cues rendered on the PC (tools/sfx-gen/games/cardler.py -> /sd/data/Cardler/pack) ----
enum { SFX_SELECT = 1, SFX_START, SFX_STEP, SFX_TALK, SFX_CHEST, SFX_HEAL, SFX_HURT, SFX_FAINT, SFX_WIN, SFX_PAUSE, SFX_N };
static TileCfg s_cfg;                       // sound + tilt settings (tile_blit.h, shared with Orde)
static const char *sfx_name(int id)
{
    static const char *const N[SFX_N] = { "x", "select", "start", "step", "talk", "chest", "heal", "hurt", "faint", "win", "pause" };
    return id > 0 && id < SFX_N ? N[id] : "x";
}
static int sfx_recipe(int id, notify_voice_t *v)   // the tone a cue falls back to without the pack
{
    static const uint16_t HZ[SFX_N] = { 0, 880, 660, 140, 990, 1320, 1170, 200, 160, 1050, 520 };
    notify__voice(&v[0], HZ[id > 0 && id < SFX_N ? id : 1], 0.0f, 0.07f);
    return 1;
}
static bool sfx_important(int id) { return id == SFX_CHEST || id == SFX_HURT || id == SFX_FAINT || id == SFX_WIN || id == SFX_START; }
static const game_sfx_t s_sfx = { DIRP, sfx_name, sfx_recipe, SFX_N - 1, 1, 16000, sfx_important, &s_cfg.audio };
static inline void sfx(int id) { game_sfx_play(&s_sfx, id); }

// ---- run state: the framework's per-app RAM (APP_RAM), 0 B while the game is closed ----
typedef struct { int x, y, lo, hi; int8_t vx, vy; uint8_t face, sprite, kind, line; int pause; } Ent;
typedef struct { int16_t x, y, v; uint8_t t, gold; } Pop;               // a rising "+12" / "-1"
typedef struct { Ent ent[NENT]; uint16_t open[MAXCHEST]; int nopen; Pop pop[NPOP]; char toast[32]; } Run;
static Run *R;

static TileAtlas s_atlas;                   // 4 KB heap chunks while open
static bool     s_atlas_ok = false;
static int      s_px, s_py;                 // player centre, world pixels
static float    s_vx = 0, s_vy = 0, s_accx = 0, s_accy = 0;   // velocity + sub-pixel accumulator
static int      s_fdx = 0, s_fdy = 1;       // facing (last move dir) — used by interact()
static int      s_face = 0;                 // 0 right, 1 left (sprite mirror)
static int      s_hp = HPMAX, s_gold = 0, s_hurt = 0, s_shake = 0;
static int      s_nchest = 0;               // chests in the world (counted once)
static bool     s_won = false;              // every chest found (the run goes on: explore freely)
static int      s_start_x, s_start_y;       // the village spawn ('@')
static int64_t  s_last_us = 0, s_poll_us = 0;
static int      s_dlg = -1;                 // open dialogue: npc_line() index, -1 = none
static int      s_toast_t = 0;
static int      s_legend_t = 0;             // frames left of the controls legend shown when play starts
static uint32_t s_frame = 0;
static bool     s_moving = false;
static bool     s_has_save = false, s_ingame = false;

static inline const uint8_t *T(int i) { return tile_px(&s_atlas, i); }

